def components(g):
 h,w=len(g),len(g[0]); bg=max({v:sum(row.count(v) for row in g) for v in set(sum(g,[]))},key=lambda x:sum(row.count(x) for row in g));seen=set();cs=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]==bg or (r,c) in seen:continue
   color=g[r][c];q=[(r,c)];seen.add((r,c));cells=[]
   while q:
    y,x=q.pop();cells.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:seen.add((yy,xx));q.append((yy,xx))
   cs.append((color,cells))
 return bg,cs
